```python cell
def statement():
  global Debug
  if Debug:
    printMark('stmt start')
  if SC.sym == IDENT:  # x := y, y(...), x ← y(...)
    # type(x) == Proc, StdProc: check no result parameters needed; call, y := true, x
    # type(x) ≠ Proc, StdProc: x := designator():
    #   sym == BECOMES: assignment; call := false
    #   sym == LARROW: check result paramter match, type(y) is Proc, StdProc,
    # record SC.val in case it is a class method (j.setGrade)
    tmp = SC.val
    # ST.printSymTab()
    x = find(SC.val)
    # the boolean classMet represent whether x is a class method
    classMet = False
    if type(x) in {Proc, StdProc}:  # call
      if type(x) == Proc:
        # print("Proc found", x)
        # each Proc type has an attribute recording if
        # it is a class method
        classMet = x.classMet
      if x.res != []:
        mark('designator for result expected')
      getSym()
      call, y, x = True, x, None
    elif type(x) in {Var, Ref}:
      x = designator()
      if SC.sym == BECOMES:
        getSym()
        y = expression()
        call = False  # x := y
        if x.tp == y.tp in {Bool, Int}:
          x = CG.genAssign(x, y)
        else:
          mark('incompatible assignment')
      elif SC.sym == LARROW:
        getSym()
        if SC.sym == IDENT:
          y = find(SC.val)
          getSym()
          call = True
        else:
          mark('procedure identifier expected')
        if type(y) in {Proc, StdProc}:
          if len(y.res) != 1 or x.tp != y.res[0].tp:
            mark('incompatible call')
        else:
          mark('procedure expected')
      else:
        mark(':= or ← expected')
    else:
      mark('variable or procedure expected')
    if call:  # call y(ap) or x ← y(ap)
      # print("a calll for ", y, "with par: ")
      # for each in y.par:
      #    print(each, "type:", type(each))
      # print("end of par")
      fp, ap, i = y.par, [], 0  #  list of formals, list of actuals
      # this is a class method, so it starts with self
      if classMet:
        # j.setGrade -> objName = j
        objName = tmp.split('.')[0]
        # print("--",procName, tmp, objName)
        # find the name (e.g. j) in symbol table
        obj = find(objName)
        # pass the base address
        ap.append(CG.genActualPara(obj, fp[0], 0))
        i = i + 1
      if SC.sym == LPAREN:
        getSym()
      else:
        mark("'(' expected")
      if SC.sym in FIRSTEXPRESSION:
        a = expression()
        if i < len(fp):
          if fp[i].tp == a.tp:
            ap.append(CG.genActualPara(a, fp[i], i))
          else:
            mark('incompatible parameter')
        else:
          mark('extra parameter')
        i = i + 1
        while SC.sym == COMMA:
          getSym()
          a = expression()
          if i < len(fp):
            if fp[i].tp == a.tp:
              ap.append(CG.genActualPara(a, fp[i], i))
            else:
              mark('incompatible parameter')
          else:
            mark('extra parameter')
          i = i + 1
      if SC.sym == RPAREN:
        getSym()
      else:
        mark("')' expected")
      if i < len(fp):
        mark('too few parameters')
      elif type(y) == StdProc:
        if y.name == 'read':
          x = CG.genRead(x)
        elif y.name == 'write':
          x = CG.genWrite(a)
        elif y.name == 'writeln':
          x = CG.genWriteln()
      else:
        # print("At gencall, x, y, ap",x, y, ap)
        x = CG.genCall(x, y, ap)
  elif SC.sym == IF:
    getSym()
    x = expression()
    if x.tp == Bool:
      x = CG.genThen(x)
    else:
      mark('boolean expected')
    if SC.sym == THEN:
      getSym()
    else:
      mark("'then' expected")
    y = statementSuite()
    if SC.sym == ELSE:
      getSym()
      y = CG.genElse(x, y)
      z = statementSuite()
      x = CG.genIfElse(x, y, z)
    else:
      x = CG.genIfThen(x, y)
  elif SC.sym == WHILE:
    getSym()
    t = CG.genWhile()
    x = expression()
    if x.tp == Bool:
      x = CG.genDo(x)
    else:
      mark('boolean expected')
    if SC.sym == DO:
      getSym()
    else:
      mark("'do' expected")
    y = statementSuite()
    x = CG.genWhileDo(t, x, y)
  else:
    mark('statement expected')
  if Debug:
    printMark('stmt end')
  return x
```

